/**
 * Learning API - 在线学习课程接口
 * 
 * 接口列表:
 * - getCourses: 获取所有课程 (支持筛选)
 * - getCourseDetail: 获取单个课程详情
 * - getCategories: 获取课程分类
 */

import request from './request.js'

export default {
  /**
   * 获取所有课程
   * @param {object} params - 查询参数 { category, level, search, page, limit }
   */
  getCourses(params = {}) {
    return request.get('/learning', { params })
  },

  /**
   * 获取单个课程详情
   * @param {string} id - 课程ID
   */
  getCourseDetail(id) {
    return request.get(`/learning/${id}`)
  },

  /**
   * 获取课程分类
   */
  getCategories() {
    return request.get('/learning/categories')
  }
}
